      // 字幕批量编辑 / SRT 导入导出（M31）
      const [edSubSel, setEdSubSel] = useState([])
      const [edSubBatch, setEdSubBatch] = useState({ shift: '0.5', dur: '1.5', find: '', repl: '' })
      const [edSubBatchOpen, setEdSubBatchOpen] = useState(true)
      const [edSrtPath, setEdSrtPath] = useState('')
      const edSrtReplaceRef = useRef(null)
      const edSrtAppendRef = useRef(null)

      const [edBatchSel, setEdBatchSel] = useState({})
      const [edBatchBusy, setEdBatchBusy] = useState(false)
      const edBatchExport = async () => {
        const targets = edProjects.filter((p) => edBatchSel[p.id] && !p.error)
        if (!targets.length || edBatchBusy) return
        setEdBatchBusy(true)
        let ok = 0
        try {
          for (const p of targets) {
            try {
              const { data } = await api(`/digital-human-studio/project?id=${encodeURIComponent(p.id)}`)
              if (!data || !data.success || !data.recipe) throw new Error((data && data.error) || '读不到配方')
              await edStartExport(data.recipe, p.name)
              ok += 1
            } catch (e) {
              setEdMsg(`「${p.name}」提交失败：${(e && e.message) || e}`)
            }
          }
          setEdMsg(`批量出片已提交 ${ok}/${targets.length} 条，进度见下方队列`)
        } finally {
          setEdBatchBusy(false)
        }
      }
      const [edSafeZones, setEdSafeZones] = useState(true)
      const [edZoom, setEdZoom] = useState(1)
      // 预览画布真实可用区（中央容器实测，扣除 padding），保证画布始终等比适配、不压变形。
      const [edPreviewBox, setEdPreviewBox] = useState({ w: 640, h: 360 })
      const edPreviewHostRef = useRef(null)
      useEffect(() => {
        const el = edPreviewHostRef.current
        if (!el) return undefined
        const read = () => {
          const w = Math.max(120, el.clientWidth - 32)
          const h = Math.max(80, el.clientHeight - 32)
          setEdPreviewBox((p) => (p.w === w && p.h === h ? p : { w, h }))
        }
        read()
        if (typeof ResizeObserver === 'undefined') return undefined
        const ro = new ResizeObserver(read)
        ro.observe(el)
        return () => ro.disconnect()
      }, [!!edData])
      const [edInspectorOpen, setEdInspectorOpen] = useState(false)
      const [edSnap, setEdSnap] = useState(true)
      const [edSnapPanel, setEdSnapPanel] = useState(false)
      const [edSnapRules, setEdSnapRules] = useState({ clip: true, playhead: true, grid: true, threshold: 0.12 })
      const [edLookLive, setEdLookLive] = useState(null)
      const [edTrackVis, setEdTrackVis] = useState(ED_TRACK_VIS0)
      const [edTrackLock, setEdTrackLock] = useState(ED_TRACK_LOCK0)
      const [edTrackH, setEdTrackH] = useState({})
      const [edTimelineH, setEdTimelineH] = useState(() => {
        try {
          const v = Number(localStorage.getItem('xcy.editor.timelineH'))
          return Number.isFinite(v) && v >= 160 ? Math.min(560, v) : 248
        } catch (e) { return 248 }
      })
      const [edTrackMute, setEdTrackMute] = useState(ED_TRACK_MUTE0)
      const [packOpts, setPackOpts] = useState({ luts: [], graphics: [] })
      const [pack, setPack] = useState({
        avoidPerson: false, cutOnPause: false, bgmAuto: false,
        highlightOn: false, highlightColor: '#ffd600',
        lut: '', bgBlur: 0,
        introText: '', introSub: '', outroText: '', outroSub: '',
        graphicOn: false, graphicType: 'arrow', graphicAt: 2.5,
        graphicX: 0.7, graphicY: 0.5, graphicSize: 0.22,
      })
      const setPackField = (k, v) => setPack((cur) => ({ ...cur, [k]: v }))

      // 包装设置的数据源（LUT / 图形种类）：引擎没起时留空，不影响普通渲染
      useEffect(() => {
        let alive = true
        ;(async () => {
          try {
            const { data } = await api('/digital-human-studio/pack_options')
            if (!alive || !data) return
            setPackOpts({
              luts: (data.luts && data.luts.luts) || [],
              graphics: (data.graphics && data.graphics.kinds) || [],
              subStyles: (data.subtitle_styles && data.subtitle_styles.styles) || [],
            })
          } catch (e) { /* 引擎离线时用默认项 */ }
        })()
        return () => { alive = false }
      }, [])

      // 拉配方列表（进页面一次就够）
      useEffect(() => {
        let alive = true
        ;(async () => {
          try {
            const { data } = await api('/digital-human-studio/recipes')
            if (!alive) return
            const items = (data && data.items) || []
            setRecipes(items)
            if (items.length) setRecipePath((cur) => cur || items[0].path)
          } catch (e) { /* 引擎没起也不影响其它 tab */ }
        })()
        return () => { alive = false }
      }, [])

      // 渲染中每 1.2 秒问一次进度
      useEffect(() => {
        if (!job || !job.task_id) return undefined
        if (job.status === 'done' || job.status === 'error' || job.status === 'cancelled') return undefined
        const timer = setInterval(async () => {
          try {
            const { data } = await api(`/digital-human-studio/render_status?task_id=${encodeURIComponent(job.task_id)}`)
            if (data && data.status) setJob((cur) => ({ ...(cur || {}), ...data }))
          } catch (e) { /* 单次失败不算错，下次再问 */ }
        }, 1200)
        return () => clearInterval(timer)
      }, [job && job.task_id, job && job.status])

      // 勾选项 → 配方补丁（没勾的不传，后端就保持原配方）
      const buildPack = () => {
        const p = {}
        if (pack.avoidPerson) p.avoid_person = true
        if (pack.cutOnPause) p.cut_on_pause = true
        if (pack.bgmAuto) p.bgm_auto = true
        if (pack.highlightOn) p.highlight_color = pack.highlightColor || '#ffd600'
        if (subStyle) p.subtitle_style = subStyle
        if (pack.lut) p.lut = pack.lut
        if (pack.bgBlur > 0) p.bg_blur = Number(pack.bgBlur)
        if (pack.introText.trim()) p.intro = { text: pack.introText.trim(), sub: pack.introSub.trim() || undefined }
        if (pack.outroText.trim()) p.outro = { text: pack.outroText.trim(), sub: pack.outroSub.trim() || undefined }
        if (pack.graphicOn) {
          p.graphic = {
            type: pack.graphicType,
            at: Number(pack.graphicAt) || 0,
            x: Number(pack.graphicX), y: Number(pack.graphicY),
            size: Number(pack.graphicSize) || 0.22,
          }
        }
        return p
      }
      const packCount = Object.keys(buildPack()).filter((k) => k !== 'subtitle_style').length

      const startRender = async () => {
        if (!recipePath) return
        const packBody = buildPack()
        const usePack = Object.keys(packBody).length > 0
        try {
          const { data } = await api(usePack ? '/digital-human-studio/render_pack' : '/digital-human-studio/render', {
            method: 'POST',
            body: JSON.stringify(usePack
              ? { path: recipePath, preset, pack: packBody }
              : { path: recipePath, preset }),
          })
          if (data && data.task_id) {
            setJob({
              ...data, status: data.status || 'queued', progress: 0,
              applied: data.applied || [],
            })
          } else {
            setJob({ status: 'error', message: (data && data.error) || '提交失败' })
          }
        } catch (e) {
          setJob({ status: 'error', message: String(e && e.message ? e.message : e) })
        }
      }

      // 批量：同一个配方文件里的 videos[] 一起渲
      useEffect(() => {
        if (!batch || !batch.batch_id) return undefined
        if (batch.status === 'done' || batch.status === 'partial') return undefined
        const timer = setInterval(async () => {
          try {
            const { data } = await api(`/digital-human-studio/render_batch_status?batch_id=${encodeURIComponent(batch.batch_id)}`)
            if (data && data.batch_id) setBatch(data)
          } catch (e) { /* 下次再问 */ }
        }, 2000)
        return () => clearInterval(timer)
      }, [batch && batch.batch_id, batch && batch.status])

